module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [15:0] count2;
    reg [1:0] state;
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'd0;
            delay <= 4'd0;
            count2 <= 16'd0;
            state <= 2'd0;
            done <= 1'b0;
            counting <= 1'b0;
        end else begin
            case (state)
                2'd0: begin // Waiting for 1101.
                    if (data & ~delay[0]) delay <= 4'd1;
                    else if (~data & delay[0]) delay <= 4'd0;
                    if (data & delay[0] & ~delay[1]) delay <= 4'd2;
                    else if (~(data & delay[0]) & delay[1]) delay <= 4'd1;
                    if (data & delay[0] & delay[1] & ~delay[2]) delay <= 4'd3;
                    else if (~(data & delay[0] & delay[1]) & delay[2]) delay <= 4'd2;
                    if (data & delay[0] & delay[1] & delay[2] & ~delay[3]) begin
                        state <= 2'd1;
                        count2 <= (delay + 1) * 1000;
                        counting <= 1'b1;
                    end
