// Same as the description in the prompt, but this time the count output
// is an integer (0 to 15) rather than a 4-bit register, which makes the
// combinational path shorter and therefore the circuit faster.
module TopModule(
    input  clk,
    input  reset,
    input  data,
    output [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [3:0] count_int;
    reg [3:0] i;
    reg [3:0] pattern;
    reg [3:0] remaining;
    reg [3:0] counter;
    wire pattern_end = (pattern == 4'hD);
    wire [3:0] next_pattern = {data, pattern[3:1]};
    wire [3:0] next_count = {data, count_int[3:1]};
    always @(*) begin
        if (counting) begin
            counter = counter + 1;
            remaining = delay - counter / 1000;
            if (counter == (delay + 1) * 1000) begin
                counting = 0;
                done = 1;
            end
        end else begin
            counter = 0;
            remaining = delay;
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            delay <= 4'h0;
            count_int <= 4'h0;
            i <= 4'h0;
            pattern <= 4'h0;
            remaining <= 4'h0;
            counting <= 0;
            done <= 0;
        end else begin
            if (counting) begin
                count_int <= count_int + 1;
            end
            if (i == 4'h4) begin
                if (pattern_end) begin
                    delay <= count_int[3:0];
                    i <= 4'h0;
                    count_int <= 4'h0;
                    pattern <= 4'h0;
                    counting <= 1;
                    done <= 0;
                end else begin
                    i <= 4'h0;
                    count_int <= 4'h0;
                    pattern <= 4'h0;
                end
            end else begin
                if (pattern_end) begin
                    i <= 4'h0;
                    count_int <= 4'h0;
                    pattern <= 4'h0;
                end else begin
                    i <= i + 1;
                    pattern <= next_pattern;
                    count_int <= next_count;
                end
            end
            if (ack && done) begin
                done <= 0;
            end
        end
    end
    assign count = count_int;
endmodule

