// One-shot: goes high for one clock cycle, then goes low.
module OneShot(input clk, input reset, input go, output reg done);
  reg latched;
  always @(posedge clk) begin
    if (reset) begin
      latched <= 0;
      done <= 0;
    end else begin
      if (go && !latched) begin
        latched <= 1;
        done <= 1;
      end else if (!go) latched <= 0;
    end
  end
endmodule

