// The TopModule implements a timer that counts for a variable number of
// clock cycles, and starts counting as soon as the input pattern 1101 is
// detected, and shifts in another 4 bits to set the delay. It then waits
// for the counter to finish counting, and notifies the user before
// resuming searching for the next input sequence.
module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [11:0] counter;
    reg [3:0] remaining;
    reg [3:0] delay2;
    reg [3:0] remaining2;
    reg [1:0] state;
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            counter <= 12'd0;
            remaining <= 4'd0;
            remaining2 <= 4'd0;
            delay <= 4'd0;
            delay2 <= 4'd0;
            count <= 4'd0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            case (state)
                2'b00: begin // searching for start sequence 1101
                    if (data && !delay) begin
                        state <= 2'b01;
                        counter <= 12'd1;
                        remaining <= 4'd1000;
                        delay2 <= 4'd0;
                    end else if (data) begin
                        delay <= delay + 1;
                    end
                end
                2'b01: begin // shifting in delay bits
                    if (counter == 12'd0) begin
                        state <= 2'b10;
                        counting <= 1'b1;
                        delay2 <= delay;
                        remaining2 <= delay + 1;
                    end else begin
                        counter <= counter - 1;
                        remaining <= remaining - 1;
                        if (remaining == 4'd0) begin
                            delay <= delay - 1;
                            remaining <= 4'd1000;
                        end
                    end
                end
                2'b10: begin // counting
                    if (counter == 12'd0) begin
                        state <= 2'b11;
                        counting <= 1'b0;
                        done <= 1'b1;
                    end else begin
                        counter <= counter - 1;
                        remaining2 <= remaining2 - 1;
                        if (remaining2 == 4'd0) begin
                            count <= count + 1;
                            remaining2 <= 4'd1000;
                        end
                    end
                end
                2'b11: begin // waiting for ack
                    if (ack) begin
                        state <= 2'b00;
                        done <= 1'b0;
                    end
                end
            endcase
        end
    end
endmodule

