// Timer with a one-bit input, 4-bit count output, and done signal to notify
// the user when the timer times out. The duration of the delay is determined
// by the 4-bit input shifted in immediately after the start sequence 1101.
module TopModule(
    input  clk,
    input  reset,
    input  data,
    output [3:0] count,
    output counting,
    output done,
    input  ack
);
    reg [3:0] delay;
    reg [3:0] count_reg;
    reg counting_reg;
    reg [1:0] state;
    wire start = (state == 2'd0) && (data & ~delay[0]) && (~delay[1]) && (~delay[2]) && (~delay[3]);
    wire [3:0] next_count = (count_reg == 4'd999) ? 4'd0 : count_reg + 4'd1;
    wire counting_next = (state == 2'd1);
    wire done_next = (state == 2'd2);
    wire [1:0] state_next;
    always @* begin
        state_next = state;
        case (state)
            2'd0: if (start) state_next = 2'd1;
            2'd1: if (count_reg == 4'd999) state_next = 2'd2;
            2'd2: if (ack) state_next = 2'd0;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            delay <= 4'd0;
            count_reg <= 4'd0;
            counting_reg <= 1'd0;
            state <= 2'd0;
        end else begin
            delay <= {data, delay[3:1]};
            count_reg <= next_count;
            counting_reg <= counting_next;
            state <= state_next;
        end
    end
    assign count = count_reg;
    assign counting = counting_reg;
    assign done = done_next;
endmodule

