// One-bit timer with an input signal that starts when a specific
// pattern is detected, shifts in 4 more bits to determine the duration
// to delay, waits for the counter to finish counting, and notifies the
// user and waits for the user to acknowledge the timer before restarting.
module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [31:0] t;
    reg [1:0] state;
    reg [1:0] next_state;
    wire pat = (state == 0) && (data == 1);
    wire [1:0] pat2 = {pat, (state == 1) && (data == 1)};
    wire [1:0] pat3 = {pat2, (state == 2) && (data == 0)};
    wire [1:0] pat4 = {pat3, (state == 3) && (data == 1)};
    wire [1:0] pat5 = {pat4, (state == 4) && (data == 1)};
    wire start = (pat5 == 2'b11);
    always @(*) begin
        next_state = state + 1'b1;
        if (start) next_state = 2'b00;
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            delay <= 4'd0;
            t <= 32'd0;
            count <= 4'd0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            state <= next_state;
            if (start) begin
                delay <= {data, data, data, data};
                t <= 32'd0;
                count <= 4'd0;
                counting <= 1'b1;
            end else if (counting) begin
                t <= t + 1'b1;
                if (t == (delay + 1) * 1000 - 1) begin
                    count <= count + 1'b1;
                    if (count == 4'd1000 - 1) begin
                        counting <= 1'b0;
                        done <= 1'b1;
                    end
                    t <= 32'd0;
                end
            end
        end
    end
    always @(posedge clk) begin
        if (reset) done <= 1'b0;
        else if (start) done <= 1'b0;
        else if (ack) done <= 1'b0;
    end
endmodule

